// EndDutyModal.tsx
import React from 'react';
import { Platform, Text, View, Button, TextInput, StyleSheet } from 'react-native';
import Duty from '../duty/Duty';

// Import DateTimePicker based on the platform
const DateTimePicker = Platform.OS !== 'web'
  ? require('@react-native-community/datetimepicker').default
  : null;

interface EndDutyModalProps {
  duty: Duty;
  updateDutyDetails: (updatedDuty: Duty) => void;
  closeModal: () => void;
}

interface EndDutyModalState {
  dutyStartDateTime: Date | null;
  dutyEndDateTime: Date | null;
  isOSDAApplicable: boolean;
  isRRAApplicable: boolean;
}

class EndDutyModal extends React.Component<EndDutyModalProps, EndDutyModalState> {
  state: EndDutyModalState = {
    dutyStartDateTime: null,
    dutyEndDateTime: null,
    isOSDAApplicable: false,
    isRRAApplicable: false,
  };

  handleEndDuty = () => {
    const { duty, updateDutyDetails } = this.props;
    const { dutyStartDateTime, dutyEndDateTime, isOSDAApplicable, isRRAApplicable } = this.state;

    const updatedDuty = new Duty(duty.id, duty.trips);
    updatedDuty.setSignInAndSignOff(dutyStartDateTime!, dutyEndDateTime!);
    updatedDuty.isOSDA = isOSDAApplicable;
    updatedDuty.isRRA = isRRAApplicable;

    updateDutyDetails(updatedDuty);
  };

  renderDateTimePicker = (currentDate: Date | null, onChange: (selectedDate: Date | null) => void) => {
    if (Platform.OS !== 'web') {
      return <DateTimePicker
        value={currentDate || new Date()}
        mode="datetime"
        is24Hour={true}
        display="default"
        onChange={(event, selectedDate) => {
          onChange(selectedDate);
        }}
      />;
    } else {
      return <TextInput
        style={styles.input}
        value={currentDate ? currentDate.toISOString().substring(0, 16) : ''}
        onChange={(event) => onChange(new Date(event.nativeEvent.text))}
      />;
    }
  };

  render() {
    const { closeModal } = this.props;
    const { dutyStartDateTime, dutyEndDateTime, isOSDAApplicable, isRRAApplicable } = this.state;

    return (
      <View style={styles.modal}>
        <View style={styles.modalContent}>
          <Text style={styles.header}>End Duty</Text>
          <View>
            <Text>Duty Start Date and Time:</Text>
            {this.renderDateTimePicker(dutyStartDateTime, (selectedDate) => this.setState({ dutyStartDateTime: selectedDate }))}
          </View>
          <View>
            <Text>Duty End Date and Time:</Text>
            {this.renderDateTimePicker(dutyEndDateTime, (selectedDate) => this.setState({ dutyEndDateTime: selectedDate }))}
          </View>
          <View style={styles.checkboxGroup}>
            <Text>
              <input
                type="checkbox"
                checked={isOSDAApplicable}
                onChange={(e) => this.setState({ isOSDAApplicable: e.target.checked })}
              />
              Is OSDA Applicable
            </Text>
          </View>
          <View style={styles.checkboxGroup}>
            <Text>
              <input
                type="checkbox"
                checked={isRRAApplicable}
                onChange={(e) => this.setState({ isRRAApplicable: e.target.checked })}
              />
              Is RRA Applicable
            </Text>
          </View>
          <Button title="End Duty" onPress={this.handleEndDuty} />
          <Button title="Cancel" onPress={closeModal} />
        </View>
      </View>
    );
  }
}

const styles = StyleSheet.create({
  modal: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  modalContent: {
    width: '90%',
    backgroundColor: 'white',
    padding: 20,
    borderRadius: 10,
  },
  header: {
    fontSize: 20,
    marginBottom: 20,
  },
  input: {
    borderWidth: 1,
    borderColor: '#ddd',
    padding: 10,
    marginBottom: 10,
  },
  checkboxGroup: {
    flexDirection: 'row',
    marginBottom: 10,
  }
});

export default EndDutyModal;
